pub fn manifest_for(id: ToolId) -> &'static ToolManifestEntry {
    TOOL_MANIFEST
        .iter()
        .find(|entry| entry.id == id)
        .expect("Every ToolId has a generated manifest entry")
}

pub fn limits_for_key(key: &str) -> Option<&'static LimitsSpec> {
    LIMITS_MANIFEST.iter().find(|entry| entry.key == key)
}
